{#
  Item slot editor with short primary list + secondary detail for Potion/Scroll/Grimoire.
  Expects: prefix, n, slots, standard_items, vault_names, potion_choices, spell_names
#}
{% set vault_names = vault_names or [] %}
{% set potion_choices = potion_choices or [] %}
{% set spell_names = spell_names or [] %}
{% set cat_order = ['Weapon', 'Missile', 'Armour', 'Gear', 'Consumable'] %}

{# JSON blobs for JS #}
<script type="application/json" id="{{ prefix }}-potion-data">{{ potion_choices|tojson }}</script>
<script type="application/json" id="{{ prefix }}-spell-data">{{ spell_names|tojson }}</script>

<div class="item-slots" data-prefix="{{ prefix }}" data-count="{{ n }}">
  {% for i in range(n) %}
    {% set cur = slots[i] if slots|length > i else '' %}
    <div class="form-row item-slot-row" data-index="{{ i }}">
      <label>Slot {{ i + 1 }}</label>
      <div class="item-slot-controls">
        <select
          class="item-slot-pick"
          data-index="{{ i }}"
          aria-label="Item type for slot {{ i + 1 }}"
        >
          <option value="">— empty / custom —</option>
          {% for cat in cat_order %}
            {% set group = standard_items|selectattr('category', 'equalto', cat)|list %}
            {% if group %}
              <optgroup label="{{ cat }}">
                {% for it in group %}
                  {% set sc = it.slot_cost if it.slot_cost is defined else 1 %}
                  {% set kind = it.kind if it.kind is defined else 'simple' %}
                  <option
                    value="{{ it.name }}"
                    data-slots="{{ sc }}"
                    data-kind="{{ kind }}"
                  >
                    {{ it.name }}{% if sc > 1 %} ({{ sc }} slots){% endif %}
                  </option>
                {% endfor %}
              </optgroup>
            {% endif %}
          {% endfor %}
          {% if vault_names %}
            <optgroup label="Vault / recorded loot">
              {% for name in vault_names %}
                <option value="{{ name }}" data-slots="1" data-kind="vault">
                  {{ name }}
                </option>
              {% endfor %}
            </optgroup>
          {% endif %}
        </select>

        {# Secondary: type-specific dropdown OR free text (one visible at a time) #}
        <select
          class="item-slot-detail"
          data-index="{{ i }}"
          aria-label="Specific type for slot {{ i + 1 }}"
          hidden
        >
          <option value="">— choose type —</option>
        </select>
        <input
          id="{{ prefix }}_slot_{{ i }}"
          class="item-slot-text"
          name="{{ prefix }}_slot_{{ i }}"
          type="text"
          value="{{ cur }}"
          placeholder="___ or custom item"
          data-index="{{ i }}"
          list="{{ prefix }}_item_suggestions"
        />
      </div>
    </div>
  {% endfor %}
  <datalist id="{{ prefix }}_item_suggestions">
    {% for it in standard_items if it.kind == 'simple' %}
      <option value="{{ it.name }}"></option>
    {% endfor %}
    {% for name in potion_choices %}
      <option value="{{ name }}"></option>
    {% endfor %}
    {% for name in spell_names %}
      <option value="Scroll of {{ name }}"></option>
      <option value="Grimoire of {{ name }}"></option>
    {% endfor %}
    {% for name in vault_names %}
      <option value="{{ name }}"></option>
    {% endfor %}
  </datalist>
</div>

