{% extends "base.html" %}
{% block title %}New warband · Frostgrave{% endblock %}
{% block content %}
  <section class="hero">
    <h1>Create your warband</h1>
    <p>
      Rules from Frostgrave 2e core: start with
      <span class="gold">{{ STARTING_GOLD }} gc</span>,
      apprentice costs <span class="gold">{{ APPRENTICE_COST }} gc</span>.
      Spells: <strong>{{ OWN_SCHOOL_SPELLS }} own</strong>,
      <strong>1 from each aligned</strong>,
      <strong><span id="neutral-needed-num">{{ neutral_needed }}</span> from different neutrals</strong>,
      <strong>none from opposed</strong>.
      Casting numbers include school penalties (own +0 / aligned +2 / neutral +4 / opposed +6).
    </p>
  </section>

  <form method="post" action="{{ url_for('warband_new') }}" enctype="multipart/form-data" id="create-form">
    <input type="hidden" name="spell_order" id="spell_order" value="" />

    <details class="card" open>
      <summary><h2>1. Warband &amp; wizard</h2></summary>
      <div class="grid-2">
        <div class="form-row">
          <label for="warband_name">Warband name</label>
          <input id="warband_name" name="warband_name" type="text" required placeholder="The Frozen Hand" />
        </div>
        <div class="form-row">
          <label for="wizard_name">Wizard name</label>
          <input id="wizard_name" name="wizard_name" type="text" required placeholder="Morvain" />
        </div>
        <div class="form-row">
          <label for="school">School of magic</label>
          {# fgNewReload is defined by the Source books card below; it rebuilds the
             URL with both the school and the ticked books, so changing one never
             discards the other. #}
          <select id="school" name="school" onchange="window.fgNewReload()">
            {% for s in schools %}
              <option value="{{ s }}" {% if s == school %}selected{% endif %}>{{ s }}</option>
            {% endfor %}
          </select>
          <div class="limit-bar" id="relations-summary" style="margin-top:0.5rem">
            <div class="limit">Own (+0 CN): <strong>{{ school }}</strong></div>
            <div class="limit">Aligned (+2): {{ relations.aligned|join(', ') }}</div>
            <div class="limit">Neutral (+4): {{ relations.neutral|join(', ') }}</div>
            <div class="limit bad">Opposed (+6, locked at start): {{ relations.opposed }}</div>
          </div>
        </div>
        <div class="form-row">
          <label for="wizard_portrait">Wizard picture</label>
          <input id="wizard_portrait" name="wizard_portrait" type="file" accept="image/*" />
        </div>
      </div>
      <p class="muted">Starting wizard stats: Move 6 · Fight +2 · Shoot +0 · Armour 10 · Will +4 · Health 14</p>

      <h3 style="margin-top:1.35rem">Apprentice (optional)</h3>
      <p class="muted">
        Name + picture only. Stats auto: Move same, Fight −2, Shoot same, Armour 10, Will −2, Health −2 from wizard.
        Same spells (cast with −2 to the roll). Cost: <span class="gold">{{ APPRENTICE_COST }} gc</span>.
      </p>
      <div class="checkbox-row">
        <input id="with_apprentice" name="with_apprentice" type="checkbox" />
        <label for="with_apprentice" style="margin:0">Hire apprentice (−{{ APPRENTICE_COST }} gc)</label>
      </div>
      <div class="grid-2">
        <div class="form-row">
          <label for="apprentice_name">Apprentice name</label>
          <input id="apprentice_name" name="apprentice_name" type="text" placeholder="Sable" />
        </div>
        <div class="form-row">
          <label for="apprentice_portrait">Apprentice picture</label>
          <input id="apprentice_portrait" name="apprentice_portrait" type="file" accept="image/*" />
        </div>
      </div>
    </details>

    {# Source books, so supplement spells can be taken as starting spells. The
       same toggles live on the warband's rules tab afterwards and can be changed
       there at any time; these just decide what the spell picker below offers. #}
    <details class="card" id="source-books-card" {% if enabled_sources_map and enabled_sources_map.values()|select|list %}open{% endif %}>
      <summary><h2>Source books <span class="muted" style="font-weight:500;font-size:0.9rem">— optional</span></h2></summary>
      <p class="muted" style="font-size:0.88rem">
        Switch on the supplements you play with. Their spells become available below, and their
        mercenaries become hireable once the warband exists. You can change this later under
        <strong>Additional Rules and Homerules</strong>.
      </p>
      <div class="stat-row" id="source-books">
        {% for book in source_books %}
          <label class="checkbox-row" style="margin:0.2rem 0">
            <input name="source_enabled_{{ book.slug }}" type="checkbox"
                   data-source-toggle
                   {% if enabled_sources_map and enabled_sources_map.get(book.name) %}checked{% endif %} />
            {{ book.name }}
          </label>
        {% endfor %}
      </div>
      {# The Maze of Malcor says the Pentangle schools are scroll-only, then gives
         rules for playing them if a group agrees — hence the extra opt-in. #}
      <label class="checkbox-row" style="margin-top:0.6rem" id="pentangle-row">
        <input name="pentangle_schools_playable" type="checkbox" data-source-toggle
               {% if pentangle_playable %}checked{% endif %} />
        Pentangle schools playable ({{ PENTANGLE_SCHOOLS|join(', ') }})
      </label>
      <p class="muted" style="font-size:0.82rem;margin:0.2rem 0 0">
        Needs The Maze of Malcor above. Their spells are scroll-only by the book; this is the
        optional rule for running them as real schools. A Pentangle wizard has two aligned schools
        instead of three, so they start with three neutral spells instead of two.
      </p>

      <script>
        // Ticking a book has to re-render the spell picker, which is built
        // server-side — same route the school dropdown already used to hit via a
        // full navigation. That reset scroll position and threw away every field
        // that isn't in the query string (name, portraits, apprentice fields), so
        // instead this fetches the same URL and swaps in just the three regions
        // that actually depend on school/sources, leaving the rest of the page —
        // and the scroll position — untouched.
        window.fgNewReload = function () {
          var params = new URLSearchParams();
          params.set("school", document.getElementById("school").value);
          document.querySelectorAll("#source-books-card input[data-source-toggle]").forEach(function (box) {
            if (box.checked) { params.set(box.name, "on"); }
          });
          var url = "{{ url_for('warband_new') }}?" + params.toString();
          // In the in-browser (Pyodide) build, a raw fetch() has no real network
          // target inside the sandboxed srcdoc iframe — window.fgFetch, when
          // present, bridges it through the driver's Python test client instead.
          (window.fgFetch || fetch)(url)
            .then(function (r) { return r.text(); })
            .then(function (html) {
              var doc = new DOMParser().parseFromString(html, "text/html");
              ["neutral-needed-num", "relations-summary", "creation-dynamic"].forEach(function (id) {
                var fresh = doc.getElementById(id);
                var current = document.getElementById(id);
                if (!fresh || !current) return;
                current.replaceWith(fresh);
              });
              window.fgInitSpellPicker();
            })
            .catch(function () { location.href = url; });
        };
        document.querySelectorAll("#source-books-card input[data-source-toggle]")
          .forEach(function (box) { box.addEventListener("change", window.fgNewReload); });
      </script>
    </details>

    <div id="creation-dynamic">
    <script type="application/json" id="creation-dynamic-data">
      {{ {
        "own": school,
        "aligned": relations.aligned,
        "neutral": relations.neutral,
        "opposed": relations.opposed,
        "need": STARTING_SPELL_COUNT,
        "ownN": OWN_SCHOOL_SPELLS,
        "neuN": neutral_needed,
      } | tojson }}
    </script>
    <details class="card" open>
      <summary><h2>2. Spells
        <span class="muted" style="font-weight:500;font-size:0.9rem">
          — <span id="spell-count">0</span> / {{ STARTING_SPELL_COUNT }}
        </span>
      </h2></summary>
      <p class="muted" style="font-size:0.88rem">Click <strong>Info</strong> on a spell line for its description (not on PDF).</p>

      <div class="limit-bar" id="spell-limits">
        <div class="limit" id="lim-own">Own ({{ school }}): <span id="own-count">0</span> / {{ OWN_SCHOOL_SPELLS }}</div>
        {% for al in relations.aligned %}
          <div class="limit" data-aligned="{{ al }}">Aligned {{ al }}: <span class="al-count">0</span> / 1</div>
        {% endfor %}
        <div class="limit" id="lim-neutral">Neutral (diff. schools): <span id="neu-count">0</span> / {{ neutral_needed }}</div>
        <div class="limit bad">Opposed {{ relations.opposed }}: locked</div>
      </div>

      <div style="margin-top:1rem">
        <h3>Available spells</h3>
        <p class="muted" style="font-size:0.85rem">
          CN shown is <strong>your effective casting number</strong> (base + school penalty).
          Greyed-out spells cannot be picked under current selection rules.
        </p>
        <details class="ref-panel" open>
          <summary>Spell list (collapse all)</summary>
          {% set schools_order = [school] + relations.aligned + relations.neutral + [relations.opposed] %}
          {% for sch in schools_order %}
            {% set rel = 'own' if sch == school else ('aligned' if sch in relations.aligned else ('opposed' if sch == relations.opposed else 'neutral')) %}
            <details class="spell-school" {% if sch == school or sch in relations.aligned %}open{% endif %}>
              <summary>
                <strong>{{ sch }}</strong>
                <span class="badge {% if rel == 'own' %}specialist{% elif rel == 'aligned' %}standard{% elif rel == 'opposed' %}dead{% endif %}">
                  {{ rel }}
                  {% if rel == 'own' %}+0{% elif rel == 'aligned' %}+2{% elif rel == 'neutral' %}+4{% else %}+6{% endif %}
                </span>
              </summary>
              <div class="spell-grid spell-grid-aligned">
                <div class="spell-list-head spell-pick-head" aria-hidden="true">
                  <span class="col-check"></span>
                  <span class="col-name">Spell</span>
                  <span class="col-cn">Your CN</span>
                  <span class="col-type">Type</span>
                  <span class="col-info"></span>
                </div>
                {% for sp in spells_for_wizard if sp.school == sch %}
                  <div class="spell-option-wrap {% if sp.relation == 'opposed' %}is-opposed{% endif %}">
                    <div class="spell-option-line">
                      <label
                        class="spell-option"
                        data-spell-id="{{ sp.id }}"
                        data-school="{{ sp.school }}"
                        data-relation="{{ sp.relation }}"
                      >
                        <span class="col-check">
                          <input
                            type="checkbox"
                            class="spell-cb"
                            name="spells"
                            value="{{ sp.id }}"
                            data-school="{{ sp.school }}"
                            data-relation="{{ sp.relation }}"
                            data-name="{{ sp.name }}"
                            data-base="{{ sp.cn }}"
                            data-eff="{{ sp.effective_cn }}"
                            {% if sp.id in selected %}checked{% endif %}
                            {% if sp.relation == 'opposed' %}disabled{% endif %}
                          />
                        </span>
                        <span class="col-name spell-name">{{ sp.name }}{% if sp.source and sp.source != 'Core Rules' %} <span class="badge">{{ sp.source }}</span>{% endif %}</span>
                        <span class="col-cn spell-cn">
                          {{ sp.effective_cn }}{% if sp.cn_penalty %}<span class="muted"> ({{ sp.cn }}+{{ sp.cn_penalty }})</span>{% endif %}
                        </span>
                        <span class="col-type spell-type muted">{{ sp.type }}</span>
                      </label>
                      <details class="spell-desc">
                        <summary class="spell-desc-toggle col-info">Info</summary>
                      </details>
                    </div>
                    <p class="spell-desc-body">{{ sp.description }}</p>
                  </div>
                {% endfor %}
              </div>
            </details>
          {% endfor %}
        </details>
      </div>

      <div style="margin-top:1.5rem">
        <h3>Selected spell order</h3>
        <p class="muted" style="font-size:0.85rem">Drag to rearrange, or use ↑ / ↓. Order is saved on the warband sheet.</p>
        <ol id="selected-list" class="selected-spells"></ol>
        <p id="spell-status" class="empty"></p>
      </div>
    </details>
    </div>

    <details class="card" open>
      <summary><h2>3. Confirm</h2></summary>
      <p class="muted" style="margin:0 0 0.75rem">
        Soldiers aren't hired here — create the warband first, then recruit from the full roster
        on the warband page (that's also where supplement mercenaries live).
      </p>
      <div class="actions">
        <button class="btn" type="submit" id="submit-btn" disabled>Create warband</button>
        <a class="btn secondary" href="{{ url_for('home') }}">Cancel</a>
      </div>
      <p class="muted" id="submit-hint" style="margin-top:0.5rem">Complete spell selection to enable create.</p>
    </details>
  </form>

  <script>
  // Re-run after every fgNewReload() swap of #creation-dynamic, since the school/
  // source-book-dependent constants and the spell checkboxes themselves are all
  // replaced then. Everything is re-read/re-queried fresh on each call rather than
  // captured once, so it's safe to call more than once per page load.
  window.fgInitSpellPicker = function () {
    const data = JSON.parse(document.getElementById('creation-dynamic-data').textContent);
    const OWN = data.own;
    const ALIGNED = data.aligned;
    const NEUTRAL = data.neutral;
    const OPPOSED = data.opposed;
    const NEED = data.need;
    const OWN_N = data.ownN;
    const NEU_N = data.neuN;  // 2 for a core school, 3 for a Pentangle one

    const selectedList = document.getElementById('selected-list');
    const spellOrder = document.getElementById('spell_order');
    const submitBtn = document.getElementById('submit-btn');
    const spellStatus = document.getElementById('spell-status');
    let order = []; // spell ids in display order

    function boxes() { return [...document.querySelectorAll('.spell-cb')]; }

    function counts() {
      const checked = boxes().filter(b => b.checked);
      const bySchool = {};
      checked.forEach(b => {
        bySchool[b.dataset.school] = (bySchool[b.dataset.school] || 0) + 1;
      });
      const own = bySchool[OWN] || 0;
      const al = {};
      ALIGNED.forEach(s => { al[s] = bySchool[s] || 0; });
      const neuSchools = NEUTRAL.filter(s => (bySchool[s] || 0) > 0);
      const neuTotal = neuSchools.reduce((a, s) => a + (bySchool[s] || 0), 0);
      return { checked, bySchool, own, al, neuSchools, neuTotal, total: checked.length };
    }

    function canAdd(school, currentlyChecked) {
      // Would checking this school be legal given current selection (excluding itself if already checked)?
      if (school === OPPOSED) return false;
      const c = counts();
      // If already checked, always allow uncheck path — handled separately
      if (currentlyChecked) return true;
      if (c.total >= NEED) return false;

      if (school === OWN) {
        return c.own < OWN_N;
      }
      if (ALIGNED.includes(school)) {
        return (c.al[school] || 0) < 1;
      }
      if (NEUTRAL.includes(school)) {
        // Need room for neutral: total neutral spells < 2, and this school not already taken (must be different schools)
        if ((c.bySchool[school] || 0) >= 1) return false;
        if (c.neuTotal >= NEU_N) return false;
        // Also: if we still need own/aligned slots, we could still pick neutral early — rules only care about final set.
        // But greying: allow neutral only if we won't exceed 2 neutrals and school free.
        return true;
      }
      return false;
    }

    /** Stricter greying: also grey neutrals/aligned if remaining slots must be filled by other requirements. */
    function canAddSmart(school, currentlyChecked) {
      if (currentlyChecked) return true;
      if (school === OPPOSED) return false;
      if (!canAdd(school, false)) return false;

      const c = counts();
      const remaining = NEED - c.total;
      if (remaining <= 0) return false;

      // Slots still required
      let needOwn = Math.max(0, OWN_N - c.own);
      let needAl = ALIGNED.reduce((n, s) => n + Math.max(0, 1 - (c.al[s] || 0)), 0);
      let needNeu = Math.max(0, NEU_N - c.neuTotal);
      // If already have a neutral from this school, can't
      // Free remaining after mandatory
      const mandatoryLeft = needOwn + needAl + needNeu;

      if (school === OWN) {
        // Can pick own if we still need own, OR if own is full we shouldn't — canAdd already handles own < 3
        // Extra own beyond 3 not allowed
        return c.own < OWN_N;
      }
      if (ALIGNED.includes(school)) {
        return (c.al[school] || 0) < 1;
      }
      if (NEUTRAL.includes(school)) {
        if ((c.bySchool[school] || 0) >= 1) return false;
        if (c.neuTotal >= NEU_N) return false;
        // If remaining slots are all needed for own/aligned, block neutral
        // After this pick, remaining-1 must cover remaining mandatory excluding this neutral
        const mandAfter = needOwn + needAl + Math.max(0, needNeu - 1);
        return (remaining - 1) >= mandAfter;
      }
      return false;
    }

    function spellsValid(c) {
      if (c.total !== NEED) return false;
      if (c.own !== OWN_N) return false;
      for (const s of ALIGNED) {
        if ((c.al[s] || 0) !== 1) return false;
      }
      if (c.neuTotal !== NEU_N) return false;
      if (c.neuSchools.length !== NEU_N) return false;
      if (c.neuSchools.some(s => (c.bySchool[s] || 0) !== 1)) return false;
      if ((c.bySchool[OPPOSED] || 0) > 0) return false;
      return true;
    }

    function refreshSpellUI() {
      const c = counts();
      document.getElementById('spell-count').textContent = c.total;
      document.getElementById('own-count').textContent = c.own;
      document.getElementById('neu-count').textContent = c.neuTotal + ' (' + c.neuSchools.join(', ') + ')';

      const limOwn = document.getElementById('lim-own');
      limOwn.classList.toggle('bad', c.own !== OWN_N && c.total === NEED);
      limOwn.classList.toggle('ok', c.own === OWN_N);

      document.querySelectorAll('[data-aligned]').forEach(el => {
        const s = el.getAttribute('data-aligned');
        const n = c.al[s] || 0;
        el.querySelector('.al-count').textContent = n;
        el.classList.toggle('ok', n === 1);
        el.classList.toggle('bad', n !== 1 && c.total === NEED);
      });

      // Grey out
      boxes().forEach(b => {
        const wrap = b.closest('.spell-option-wrap') || b.closest('.spell-option');
        const label = b.closest('.spell-option');
        if (b.dataset.relation === 'opposed') {
          b.disabled = true;
          if (wrap) wrap.classList.add('disabled');
          if (label) label.classList.add('disabled');
          return;
        }
        const allow = b.checked || canAddSmart(b.dataset.school, false);
        b.disabled = !allow && !b.checked;
        if (wrap) wrap.classList.toggle('disabled', b.disabled && !b.checked);
        if (label) label.classList.toggle('disabled', b.disabled && !b.checked);
      });

      // Sync order list
      const checkedIds = new Set(c.checked.map(b => b.value));
      order = order.filter(id => checkedIds.has(id));
      c.checked.forEach(b => {
        if (!order.includes(b.value)) order.push(b.value);
      });
      renderSelected();
      spellOrder.value = order.join('|');

      const ok = spellsValid(c);
      spellStatus.textContent = ok
        ? 'Spell selection complete.'
        : 'Need: 3 own · 1 each aligned · 2 neutrals (different schools) · 0 opposed.';
      spellStatus.className = ok ? 'muted' : 'empty';
      updateSubmit();
    }

    function renderSelected() {
      selectedList.innerHTML = '';
      order.forEach((id, idx) => {
        const b = boxes().find(x => x.value === id);
        if (!b) return;
        const li = document.createElement('li');
        li.draggable = true;
        li.dataset.id = id;
        li.innerHTML =
          '<span class="sel-main"><strong>' + b.dataset.name + '</strong> ' +
          '<span class="muted">' + b.dataset.school + '</span> ' +
          '<span class="spell-cn">CN ' + b.dataset.eff + '</span></span>' +
          '<span class="sel-btns">' +
          '<button type="button" class="btn small secondary" data-up>↑</button> ' +
          '<button type="button" class="btn small secondary" data-down>↓</button> ' +
          '<button type="button" class="btn small danger" data-rm>×</button></span>';
        li.querySelector('[data-up]').onclick = () => move(idx, -1);
        li.querySelector('[data-down]').onclick = () => move(idx, 1);
        li.querySelector('[data-rm]').onclick = () => {
          b.checked = false;
          refreshSpellUI();
        };
        li.addEventListener('dragstart', e => {
          e.dataTransfer.setData('text/plain', String(idx));
        });
        li.addEventListener('dragover', e => e.preventDefault());
        li.addEventListener('drop', e => {
          e.preventDefault();
          const from = parseInt(e.dataTransfer.getData('text/plain'), 10);
          const to = idx;
          if (isNaN(from)) return;
          const item = order.splice(from, 1)[0];
          order.splice(to, 0, item);
          spellOrder.value = order.join('|');
          renderSelected();
        });
        selectedList.appendChild(li);
      });
    }

    function move(idx, dir) {
      const j = idx + dir;
      if (j < 0 || j >= order.length) return;
      const t = order[idx];
      order[idx] = order[j];
      order[j] = t;
      spellOrder.value = order.join('|');
      renderSelected();
    }

    boxes().forEach(b => b.addEventListener('change', () => {
      if (b.checked && !canAddSmart(b.dataset.school, false)) {
        // double-check
        const c = counts();
        // if we just checked and invalid, undo unless valid
        // canAddSmart was true at click time due to disabled state
      }
      refreshSpellUI();
    }));

    // --- Submit gating (spells only; soldiers are hired later on the warband page) ---
    function updateSubmit() {
      const ok = spellsValid(counts());
      submitBtn.disabled = !ok;
      document.getElementById('submit-hint').textContent = ok
        ? 'Ready to create.'
        : 'Complete spell selection to enable create.';
    }

    refreshSpellUI();
  };

  // The form itself is never replaced by fgNewReload(), so this only needs
  // attaching once — refreshSpellUI() (called on every checkbox change and at
  // the end of every fgInitSpellPicker() run) already keeps spell_order current.
  if (!window.__fgSubmitGuardAttached) {
    window.__fgSubmitGuardAttached = true;
    document.getElementById('create-form').addEventListener('submit', function (e) {
      if (document.getElementById('submit-btn').disabled) e.preventDefault();
    });
  }

  window.fgInitSpellPicker();
  </script>
{% endblock %}

