{
 "intro": "This one arrived as scanned image pages with no text layer, so it was run through a local OCR pipeline (tesseract) page-by-page to extract it. It's also technically a related but separate Osprey ruleset — a Heritor (caster) and Warden (nature-magic specialist) lead a Crew across a chain of islands instead of a Wizard leading a Warband — so nearly everything below is structurally new relative to the Frostgrave rulebook, even where the mechanics closely parallel it. A few stat-block cells were unrecoverable from the scan (flagged with \"?\").",
 "sections": [
  {
   "title": "New core mechanics",
   "blurb": "Turn order is Heritor phase → Warden phase → Crew phase → Creature phase (3-step AI: fight if engaged, shoot/close on the nearest visible foe, else random move). Combat/shooting math mirrors core Frostgrave closely (Fight/Shoot rolls, cover, push-back), with an optional Critical Hit rule (natural 20 auto-wins and doubles damage) and an optional Wounded rule (≤4 Health = 1 action & -2 to all rolls).",
   "entries": [
    {
     "name": "Crew composition",
     "tag": "",
     "text": "Max 10: 1 Heritor + 1 Warden (mandatory, only one ever per crew) + up to 8 crewmen (max 4 paid Specialists). All rolls use d20."
    },
    {
     "name": "Building a Heritor",
     "tag": "",
     "text": "Picks 5 of 30 shared Abilities (one at Utilization Number 3, four at UN5); may raise one non-Armour stat by +1; 5 item slots."
    },
    {
     "name": "Utilization Rolls & Blood Burn (signature new subsystem)",
     "tag": "",
     "text": "Using a Heritor Ability costs 1 self-damage (\"Blood Burn\") to attempt, +2 more on a failed d20-vs-UN roll. Extra attempts the same turn stack a penalty to the UN: +0/+3/+6/+9/+12/+15 for the 1st–6th attempt — a practical cap of ~6/turn."
    },
    {
     "name": "Building a Warden",
     "tag": "",
     "text": "Base M6 F+1 S+0 A10 W+4 H14; picks a Branch (below); learns 4 starting spells (3 in-Branch, 1 out-of-Branch at +4 Casting Number); 3 item slots; can never wear armour or a shield."
    },
    {
     "name": "Split Stats",
     "tag": "",
     "text": "Notation like \"+2/+3\": first number is the true/base stat for leveling, second is the current effective stat for rolls."
    },
    {
     "name": "Empowering & resisting spells",
     "tag": "",
     "text": "A Warden can empower a cast (or her own resistance roll) by trading Health 1-for-1, even to the point of a killing cast. Targets resist vs. the higher of the final Casting Roll or 14."
    },
    {
     "name": "Swimming Rolls",
     "tag": "",
     "text": "Activating in deep water needs a Will roll (TN5, modified by armour/shield/treasure); fail = no activation + damage. Amphibious/Aquatic traits bypass it entirely."
    },
    {
     "name": "Small Boats",
     "tag": "",
     "text": "Capacity 6, moves 2\"+1\"/rider (max 6\"), -1 Fight/Shoot aboard, boarding needs a Fight roll; can be attacked (Fight+0/Armour14/Health30)."
    },
    {
     "name": "Map Stones (campaign win condition)",
     "tag": "",
     "text": "10 unique, unsellable clue-items toward the legendary Crystal Pool; +20 XP each; collecting all 10 is the stated campaign endgame."
    },
    {
     "name": "New Recruits",
     "tag": "",
     "text": "If only the Heritor dies, the Warden's level sets the replacement (capped gains); if only the Warden dies, it's the Heritor's level ÷3. Both dying disbands the crew."
    }
   ],
   "rows": []
  },
  {
   "title": "Heritor Abilities",
   "blurb": "Every Heritor is built à la carte from this same list — there's no archetype/class system the way Frostgrave has ten wizard schools.",
   "entries": [],
   "rows": [
    {
     "name": "Backswing",
     "text": "Utilized when… Wins a fight, still in combat · Effect Free extra fight action against an engaged foe."
    },
    {
     "name": "Burning Eyes",
     "text": "Utilized when… Enemy tries to move into combat · Effect Target Will TN16 or its move stops 1\" short."
    },
    {
     "name": "Catch Missile",
     "text": "Utilized when… Targeted by a bow/crossbow 6\"+ away · Effect Shot automatically fails."
    },
    {
     "name": "Crushing Blow",
     "text": "Utilized when… Wins hand-to-hand combat · Effect +3 extra damage."
    },
    {
     "name": "Daze",
     "text": "Utilized when… During own activation · Effect Target within 6\" Will TN16 or loses next activation."
    },
    {
     "name": "Deadeye",
     "text": "Utilized when… Hits with a ranged weapon on natural 18–19 · Effect Counts as a critical hit."
    },
    {
     "name": "Death Strike",
     "text": "Utilized when… Wins combat on natural 18–19 · Effect Counts as a critical hit."
    },
    {
